	// ========================================================================
	// Status codes
	// ========================================================================
	// Anonymous on purpose: a named enum in this flat header would itself be
	// reported as an uncovered public C++ entity by the parity validator.
	typedef enum
	{
		SHARD_STATUS_OK                        = 0,
		SHARD_STATUS_ERROR_INVALID_ARGUMENT    = 1,
		SHARD_STATUS_ERROR_NULL_POINTER        = 2,
		SHARD_STATUS_ERROR_OUT_OF_MEMORY       = 3,
		SHARD_STATUS_ERROR_INDEX_OUT_OF_BOUNDS = 4,
		SHARD_STATUS_ERROR_TYPE_MISMATCH       = 5,
		SHARD_STATUS_ERROR_EXECUTION_FAILED    = 6,
		SHARD_STATUS_ERROR_UNHANDLED_EXCEPTION = 7,
		SHARD_STATUS_ERROR_LENGTH_EXCEEDED     = 8,
		SHARD_STATUS_ERROR_SYMBOL_NOT_FOUND    = 9,
		SHARD_STATUS_ERROR_UNSUPPORTED         = 10,
		SHARD_STATUS_ERROR_DELETED_OPERATION   = 11
	} shard_status_t;

